<script setup lang="ts">
import OwnerInvitation from '@/features/account/OwnerInvitation.vue'
import TextSource from './TextSource.vue'
import IntakeFields from './IntakeFields.vue'
import {submitReviewedDraft} from './intake-save'
import WorkflowTimeline from './WorkflowTimeline.vue'
import {safeCaseSection,materialNames,type Workflow} from './workflow'
import MapPanel from './DispatchLocation.vue'
import DispatchWaitingPanel from './DispatchWaitingPanel.vue'
import FundsPanel from '../funds/FundsPanel.vue'
import ComplaintPanel from '../complaint/ComplaintPanel.vue'
import RepairPanel from '../repair/RepairPanel.vue'
import QuotationPanel from '../quotation/QuotationPanel.vue'
import MaterialsPanel from '../materials/MaterialsPanel.vue'
import { computed, nextTick, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElButton, ElDescriptions, ElDescriptionsItem, ElDialog, ElDrawer, ElForm, ElFormItem, ElInput, ElMessage, ElMessageBox, ElOption, ElSelect, ElTable, ElTableColumn, ElTag } from 'element-plus'
import { ApiError } from '@/shared/http/create-client'
import { currentUser, httpClient } from '@/shared/http/client'
import { label, localTime } from '@/shared/ui/presentation'
import { localDateTimeInput, statusLabels, workOrderApi, type CriticalForm, type DraftForm, type History, type RegionOption, type ShopOption, type WorkOrder } from './work-orders'

const pendingQuote=ref<{assessment:string;markup:string;mode:string}>()
const materialRevision=ref(0),receiptMaterialsOpen=ref(false)
const route=useRoute(),router=useRouter(),id=String(route.params.id),api=workOrderApi(httpClient)
const order=ref<WorkOrder>(),history=ref<History[]>([]),shops=ref<ShopOption[]>([]),regions=ref<RegionOption[]>([]),shopId=ref<number>()
const dispatchLocationDirty=ref(false),mapQueryId=ref<string>(),automaticDispatch=ref(false)
const reassignDialog=ref(false),busy=ref(false),editDialog=ref(false),criticalDialog=ref(false),loading=ref(true),loadError=ref('')

const viewportWidth=ref(window.innerWidth),detailColumns=computed(()=>viewportWidth.value>=1280?3:viewportWidth.value>=1024?2:1)
const onResize=()=>{viewportWidth.value=window.innerWidth}
const isAdmin=computed(()=>currentUser.value?.roles.includes('ADMIN')===true)
const headerElement=ref<HTMLElement>(),headerHeight=ref(164)
const workflow=ref<Workflow>()
const activeSection=computed(()=>safeCaseSection(String(route.query.section??''),workflow.value?.currentNode??'UNKNOWN',order.value?.status))
const waitingForShop=computed(()=>order.value?.status==='PENDING_ACCEPTANCE')
watch(waitingForShop,async waiting=>{if(waiting){await nextTick();window.scrollTo(0,0)}})
const receiptMode=computed(()=>activeSection.value==='repair'&&workflow.value?.currentNode==='RECEIPT')
const receiptShopName=computed(()=>{const shopId=order.value?.currentAssignment?.shopId;return shops.value.find(shop=>shop.id===shopId)?.name??(shopId?'维修网点 · ID '+shopId:undefined)})
const taskTitle=computed(()=>workflow.value?.nodes.find(n=>n.key===workflow.value?.currentNode)?.label??'历史资料待核对')
const adminOnlyCancellation=computed(()=>order.value!==undefined&&['ARRIVED','WAITING_QUOTE','QUOTE_REVIEWING','WAITING_INSURER_ASSESSMENT','WAITING_REPAIR_AUTHORIZATION','REPAIRING','WAITING_OWNER_CONFIRMATION','WAITING_INSURER_PAYMENT','WAITING_SHOP_SETTLEMENT','COMPLETED'].includes(order.value.status))
const blankDraft=():DraftForm=>({surveyorName:'',surveyorPhone:'',vehicleColor:'',insuranceCompany:'',claimNo:'',claimReportedAt:'',ownerName:'',ownerPhone:'',policyNo:'',vehicleBrand:'',vehicleModel:'',vehicleVin:'',vehiclePlate:'',vehicleOtherIdentifier:'',accidentAt:'',accidentRegionId:'',accidentAddress:'',accidentDescription:''})
const edit=reactive<DraftForm>(blankDraft())
const critical=reactive<CriticalForm>({insuranceCompany:'',claimNo:'',vehicleVin:'',vehiclePlate:'',vehicleOtherIdentifier:'',reason:''})
const local=localDateTimeInput
const historyPage=ref(1),historyTotal=ref(0),shopPage=ref(0),shopTotal=ref(0),regionPage=ref(0),regionTotal=ref(0),optionsBusy=ref(false)
async function loadHistory(){const result=await api.history(id,historyPage.value);history.value=result.records;historyTotal.value=result.total}
async function moreShops(){optionsBusy.value=true;try{const result=await api.shops(id,shopPage.value+1);shops.value.push(...result.records);shopPage.value++;shopTotal.value=result.total}catch(error){ElMessage.error(error instanceof Error?error.message:'网点加载失败')}finally{optionsBusy.value=false}}
async function moreRegions(){optionsBusy.value=true;try{const result=await api.regions(regionPage.value+1);regions.value.push(...result.records);regionPage.value++;regionTotal.value=result.total}catch(error){ElMessage.error(error instanceof Error?error.message:'区域加载失败')}finally{optionsBusy.value=false}}
const assignmentVersion=()=>{const version=order.value?.currentAssignment?.assignmentVersion;if(!version)throw new Error('当前派单版本不存在，请刷新后重试');return version}
async function load(){const [detail,flow]=await Promise.all([api.detail(id),httpClient.get<{data:Workflow}>('/work-orders/'+id+'/workflow')]);order.value=detail;workflow.value=flow.data.data;await loadHistory();if(order.value.accidentRegionId&&order.value.status!=='DRAFT'&&order.value.status!=='CANCELLED'){shops.value=[];shopPage.value=0;await moreShops()}}
async function dispatchChanged(updated?:WorkOrder){if(updated)order.value=updated;await load()}
function openEdit(){if(!order.value)return;Object.assign(edit,{surveyorName:order.value.surveyorName??'',surveyorPhone:order.value.surveyorPhone??'',vehicleColor:order.value.vehicleColor??'',insuranceCompany:order.value.insuranceCompany??'',claimNo:order.value.claimNo??'',claimReportedAt:local(order.value.claimReportedAt),ownerName:order.value.ownerName??'',ownerPhone:order.value.ownerPhone??'',policyNo:order.value.policyNo??'',vehicleBrand:order.value.vehicleBrand??'',vehicleModel:order.value.vehicleModel??'',vehicleVin:order.value.vehicleVin??'',vehiclePlate:order.value.vehiclePlate??'',vehicleOtherIdentifier:order.value.vehicleOtherIdentifier??'',accidentAt:local(order.value.accidentAt),accidentRegionId:String(order.value.accidentRegionId??''),accidentAddress:order.value.accidentAddress??'',accidentDescription:order.value.accidentDescription??''});editDialog.value=true}
function openCritical(){if(!order.value)return;Object.assign(critical,{insuranceCompany:order.value.insuranceCompany??'',claimNo:order.value.claimNo??'',vehicleVin:order.value.vehicleVin??'',vehiclePlate:order.value.vehiclePlate??'',vehicleOtherIdentifier:order.value.vehicleOtherIdentifier??'',reason:''});criticalDialog.value=true}
async function saveDraft(){busy.value=true;try{order.value=await api.update(id,edit);editDialog.value=false;ElMessage.success('草稿已保存')}catch(error){ElMessage.error(error instanceof Error?error.message:'保存失败')}finally{busy.value=false;await load()}}
async function deleteDraft(){try{await ElMessageBox.confirm('删除后不可恢复，确定删除此草稿吗？','删除草稿',{type:'warning'});await api.deleteDraft(id);ElMessage.success('草稿已删除');await router.push('/work-orders')}catch(error){if(error instanceof Error&&error.message)ElMessage.error(error.message)}}
async function submit(){busy.value=true;try{order.value=await submitReviewedDraft(api,id,crypto.randomUUID(),async()=>{const result=await ElMessageBox.prompt('发现疑似重复案件。请输入继续创建原因：','疑似重复案件',{inputValidator:value=>Boolean(value.trim())||'原因必填'});return result.value.trim()});ElMessage.success('已生成正式案件')}catch(error){if(error==='cancel'||error==='close')ElMessage.info('已取消提交');else ElMessage.error(error instanceof Error?error.message:'提交结果未确认，请刷新案件状态后重试')}finally{busy.value=false;await load()}}
async function bindOwner(){if(!order.value)return;const result=await ElMessageBox.prompt('仅匹配唯一启用车主账号，不转移已有绑定。请输入匹配原因','重新匹配车主',{inputValidator:value=>Boolean(value.trim())||'原因必填'});order.value=await api.bindOwner(id,order.value.version,result.value.trim());if(order.value.ownerBindingStatus==='BOUND')ElMessage.success('车主已绑定，可在自己账号查看案件');else ElMessage.warning('没有唯一匹配的车主账号，仍待绑定；请管理员核对手机号和重复账号')}
async function saveCritical(){busy.value=true;try{order.value=await api.critical(id,{...critical,reason:critical.reason.trim()});criticalDialog.value=false;ElMessage.success('关键字段已更新并审计')}catch(error){ElMessage.error(error instanceof Error?error.message:'更新失败')}finally{busy.value=false;await load()}}
async function dispatchNew(confirmPossibleDuplicate=false,duplicateReason:string|null=null){if(!shopId.value){ElMessage.warning('请选择维修网点');return}try{order.value=await api.dispatch(id,shopId.value,confirmPossibleDuplicate,duplicateReason,mapQueryId.value);ElMessage.success('已派单')}catch(error){if(error instanceof ApiError&&error.code==='POSSIBLE_DUPLICATE'&&!confirmPossibleDuplicate){const result=await ElMessageBox.prompt('该车主在此网点存在短期案件。请输入继续派单原因：','疑似重复案件',{inputValidator:value=>Boolean(value.trim())||'原因必填'});await dispatchNew(true,result.value.trim())}else throw error}}
async function reassign(){if(!shopId.value||!order.value){ElMessage.warning('请选择维修网点');return}const result=await ElMessageBox.prompt('请输入改派原因','改派',{inputValidator:value=>Boolean(value.trim())||'原因必填'});let transferDescription:string|null=null;let vehicleNotArrivedConfirmed=false;if(order.value.status==='PENDING_ARRIVAL'||order.value.status==='ARRIVAL_EXCEPTION'){await ElMessageBox.confirm('请确认车辆尚未到店。','改派确认',{type:'warning'});vehicleNotArrivedConfirmed=true}if(order.value.status==='ARRIVED'){const transfer=await ElMessageBox.prompt('车辆已到店，仅管理员可异常改派。请输入车辆转运说明：','异常改派',{inputValidator:value=>Boolean(value.trim())||'转运说明必填'});transferDescription=transfer.value.trim()}const value={shopId:shopId.value,assignmentVersion:assignmentVersion(),reason:result.value.trim(),vehicleNotArrivedConfirmed,transferDescription,confirmPossibleDuplicate:false};try{order.value=await api.reassign(id,value,mapQueryId.value);ElMessage.success('已改派')}catch(error){if(error instanceof ApiError&&error.code==='POSSIBLE_DUPLICATE'){await ElMessageBox.confirm('目标网点存在短期重复案件，是否仍按刚才原因继续改派？','疑似重复案件',{type:'warning'});order.value=await api.reassign(id,{...value,confirmPossibleDuplicate:true},mapQueryId.value);ElMessage.success('已记录原因并改派')}else throw error}}
async function cancelAssignment(){const result=await ElMessageBox.prompt('请输入取消派单原因','取消派单',{inputValidator:value=>Boolean(value.trim())||'原因必填'});order.value=await api.cancelAssignment(id,assignmentVersion(),result.value.trim());ElMessage.success('已取消派单')}
async function markArrivalException(){const result=await ElMessageBox.prompt('请输入到店异常原因','标记到店异常',{inputValidator:value=>Boolean(value.trim())||'原因必填'});order.value=await api.arrivalException(id,assignmentVersion(),result.value.trim());ElMessage.success('已进入到店异常')}
async function continueWaiting(){const result=await ElMessageBox.prompt('可填写继续等待说明','继续等待');order.value=await api.continueWaiting(id,assignmentVersion(),result.value.trim()||null);ElMessage.success('已恢复待到店')}
async function cancelWorkOrder(){if(order.value?.ownerBindingStatus!=='BOUND')ElMessage.info('车主未绑定，没有可通知的车主账号');if(!order.value?.currentAssignment)ElMessage.info('没有当前派单，没有可通知的网点');const reason=await ElMessageBox.prompt('请输入取消原因','取消整个工单',{inputValidator:value=>Boolean(value.trim())||'取消原因必填'});const description=await ElMessageBox.prompt('请输入取消说明','取消整个工单',{inputValidator:value=>Boolean(value.trim())||'取消说明必填'});order.value=await api.cancelWorkOrder(id,{reason:reason.value.trim(),description:description.value.trim(),notifyOwner:order.value?.ownerBindingStatus==='BOUND'?window.confirm('是否发送站内通知给绑定车主？'):false,notifyShop:order.value?.currentAssignment?window.confirm('是否发送站内通知给本次派单网点？'):false});ElMessage.success('工单已取消')}
async function run(action:()=>Promise<void>){busy.value=true;try{await action()}catch(error){if(error instanceof Error&&error.message)ElMessage.error(error.message)}finally{busy.value=false;await load()}}
let headerSizeObserver:ResizeObserver|undefined
function observeHeaderSize(){if(!headerSizeObserver&&headerElement.value){headerSizeObserver=new ResizeObserver(()=>{headerHeight.value=Math.ceil(headerElement.value?.getBoundingClientRect().height??164)});headerSizeObserver.observe(headerElement.value)}}
function onFocus(){if(busy.value||!order.value)return;materialRevision.value++;void load().catch(e=>ElMessage.error(e instanceof Error?e.message:'刷新失败'))}
async function initialLoad(){loading.value=true;loadError.value='';order.value=undefined;try{await load();try{await moreRegions()}catch(error){ElMessage.warning(error instanceof Error?error.message:'区域列表暂不可用')}await nextTick();observeHeaderSize()}catch(error){loadError.value=error instanceof Error?error.message:'加载失败';order.value=undefined}finally{loading.value=false}}
onMounted(()=>{window.addEventListener('resize',onResize);window.addEventListener('focus',onFocus);void initialLoad()});onUnmounted(()=>{window.removeEventListener('resize',onResize);window.removeEventListener('focus',onFocus);headerSizeObserver?.disconnect()});watch(()=>[loading.value,viewportWidth.value],async()=>{await nextTick();observeHeaderSize()})
</script>


<template><main class="work-page workflow-page" :style="{'--workflow-header-height':headerHeight+'px'}"><div v-if="loading" class="workflow-skeleton" aria-busy="true"><span/><span/><span/></div><div v-else-if="loadError" class="detail-state" role="alert">{{ loadError }} <ElButton @click="initialLoad">重试</ElButton></div><template v-if="!loading&&order&&workflow"><header ref="headerElement" class="workflow-header glass"><div class="header-line"><div><ElButton text @click="router.push('/work-orders')">返回案件</ElButton><h1>{{ order.businessNo || '案件草稿' }}</h1><p class="header-facts">{{ order.ownerName||order.ownerPhone }} · {{ order.vehiclePlate||order.vehicleVin||order.vehicleModel }} · {{ order.insuranceCompany }}</p></div><div class="header-tools"><ElTag>{{ statusLabels[order.status] }}</ElTag><ElButton :disabled="busy" @click="materialRevision++;run(load)">刷新</ElButton><details v-if="!waitingForShop"><summary>更多</summary><div class="actions"><ElButton v-if="isAdmin&&order.status==='ARRIVED'" @click="reassignDialog=true">异常改派</ElButton><ElButton v-if="order.ownerBindingStatus==='PENDING'&&!['DRAFT','CANCELLED','COMPLETED','CLOSED'].includes(order.status)" :loading="busy" @click="run(bindOwner)">重新匹配车主</ElButton><ElButton v-if="order.status==='DRAFT'" @click="openEdit">编辑草稿</ElButton><ElButton v-if="order.status==='DRAFT'" type="danger" plain @click="deleteDraft">删除草稿</ElButton><ElButton v-if="order.status!=='DRAFT'&&order.status!=='CANCELLED'&&order.status!=='CLOSED'&&order.status!=='COMPLETED'" @click="openCritical">修改关键字段</ElButton><ElButton v-if="order.status!=='DRAFT'&&order.status!=='CANCELLED'&&order.status!=='CLOSED'&&order.status!=='COMPLETED'&&(!adminOnlyCancellation||isAdmin)" type="danger" plain :loading="busy" @click="run(cancelWorkOrder)">取消整个工单</ElButton></div></details></div></div><WorkflowTimeline :workflow="workflow"/></header><template v-if="waitingForShop"><DispatchWaitingPanel :order="order"/></template><template v-else><nav class="related-links" aria-label="关联事项"><ElButton v-if="order.status!=='COMPLETED'" :type="!['funds','complaint','history','overview'].includes(activeSection)?'primary':undefined" @click="router.replace({path:route.path})">当前任务</ElButton><ElButton v-for="item in [{key:'overview',name:receiptMode?'案件详情':'案件资料'},{key:'history',name:'记录'}]" :key="item.key" :type="order.status==='COMPLETED'&&activeSection===item.key?'primary':undefined" :text="order.status!=='COMPLETED'||activeSection!==item.key" :disabled="order.status==='DRAFT'&&['funds','complaint'].includes(item.key)" @click="router.replace({path:route.path,query:{section:item.key}})">{{ item.name }}</ElButton></nav><div class="workflow-layout" :class="{'receipt-layout':receiptMode,'completed-layout':order.status==='COMPLETED'}"><article class="task-surface"><details v-if="pendingQuote&&activeSection!=='quotation'" class="pending-input"><summary>未提交信息</summary><p>核损金额 {{ pendingQuote.assessment||'未填写' }} 元 · {{ pendingQuote.mode==='PERCENTAGE'?'加价比例':'加价金额' }} {{ pendingQuote.markup }}。信息仅保留在本页，当前流程以时间轴为准。</p></details><p v-if="workflow.legacyNeedsReview" class="legacy-note" role="status">历史资料待核对，当前进度保留。</p><div v-if="activeSection==='overview'" data-reading="案件资料"><h2>案件资料</h2><TextSource :case-id="id"/><details :open="order.status==='DRAFT'"><summary>物损照片与材料记录</summary><MaterialsPanel :case-id="id" :status="order.status" :allowed-categories="order.status==='DRAFT'?['SCENE_PHOTO']:[]" :assignment-version="order.currentAssignment?.assignmentVersion"/></details><ElDescriptions :column="detailColumns" border><ElDescriptionsItem label="报案号">{{ order.claimNo }}</ElDescriptionsItem><ElDescriptionsItem label="保险公司">{{ order.insuranceCompany }}</ElDescriptionsItem><ElDescriptionsItem label="数据来源">{{ order.dataSource }}</ElDescriptionsItem><ElDescriptionsItem label="当前负责人">{{ order.currentResponsibleId }}</ElDescriptionsItem><ElDescriptionsItem label="车主端可见性">{{ order.status==='DRAFT'?'草稿尚未提交':order.ownerBindingStatus==='BOUND'?'已绑定车主账号':'待绑定：核对车主手机号后重新匹配' }}</ElDescriptionsItem><ElDescriptionsItem label="车主">{{ order.ownerName }}</ElDescriptionsItem><ElDescriptionsItem label="手机">{{ order.ownerPhone }}</ElDescriptionsItem><ElDescriptionsItem label="查勘员">{{ order.surveyorName }} {{ order.surveyorPhone }}</ElDescriptionsItem><ElDescriptionsItem label="车辆颜色">{{ order.vehicleColor }}</ElDescriptionsItem><ElDescriptionsItem label="车辆">{{ order.vehicleBrand }} {{ order.vehicleModel }}</ElDescriptionsItem><ElDescriptionsItem label="VIN">{{ order.vehicleVin || '-' }}</ElDescriptionsItem><ElDescriptionsItem label="牌照/其他">{{ order.vehiclePlate || order.vehicleOtherIdentifier || '-' }}</ElDescriptionsItem><ElDescriptionsItem label="事故地址" :span="Math.min(2,detailColumns)">{{ order.accidentAddress || '未填写详细地址' }}</ElDescriptionsItem><ElDescriptionsItem label="事故时间">{{ order.accidentAt }}</ElDescriptionsItem><ElDescriptionsItem label="事故说明" :span="detailColumns">{{ order.accidentDescription }}</ElDescriptionsItem></ElDescriptions><OwnerInvitation v-if="!['DRAFT','CANCELLED','COMPLETED','CLOSED'].includes(order.status)" :case-id="id" :version="order.version" @changed="load"/><div v-if="order.status==='DRAFT'" class="workflow-action"><ElButton @click="openEdit">完善建单信息</ElButton><ElButton type="primary" :loading="busy" @click="submit">继续</ElButton></div></div><section v-if="activeSection==='dispatch'" class="panel"><h2>派单与异常处理</h2><MapPanel v-if="['PENDING_DISPATCH','PENDING_ACCEPTANCE','PENDING_ARRIVAL','ARRIVAL_EXCEPTION'].includes(order.status)" :case-id="id" :order="order" :selected-shop-id="shopId" @select="shopId=$event" @recommendation="mapQueryId=$event" @automatic="automaticDispatch=$event" @changed="dispatchChanged" @pending="dispatchLocationDirty=$event"/><p v-if="!['PENDING_DISPATCH','PENDING_ACCEPTANCE','PENDING_ARRIVAL','ARRIVAL_EXCEPTION','ARRIVED'].includes(order.status)">当前阶段无可执行的派单或到店异常操作。</p><div v-else class="inline"><ElSelect v-if="order.status==='ARRIVED'" v-model="shopId" filterable placeholder="选择服务区域内网点"><ElOption v-for="item in shops" :key="item.id" :label="item.name+(item.distanceMetres!=null?' · 模拟'+(item.distanceMetres/1000).toFixed(2)+' km':' · 距离未知')" :value="item.id"/></ElSelect><ElButton v-if="order.status==='ARRIVED'&&shops.length<shopTotal" :disabled="optionsBusy" @click="moreShops">加载更多网点（{{ shops.length }}/{{ shopTotal }}）</ElButton><ElButton v-if="order.status==='PENDING_DISPATCH'&&!automaticDispatch" type="primary" :disabled="dispatchLocationDirty||!order.dispatchAddressConfirmed||!shopId" :loading="busy" @click="run(()=>dispatchNew())">派单</ElButton><ElButton v-if="['PENDING_ACCEPTANCE','PENDING_ARRIVAL','ARRIVAL_EXCEPTION'].includes(order.status)||(order.status==='ARRIVED'&&isAdmin)" :disabled="dispatchLocationDirty||!order.dispatchAddressConfirmed||!shopId" :loading="busy" @click="run(()=>reassign())">改派</ElButton><ElButton v-if="['PENDING_ACCEPTANCE','PENDING_ARRIVAL','ARRIVAL_EXCEPTION'].includes(order.status)" type="danger" plain :loading="busy" @click="run(cancelAssignment)">取消派单</ElButton><ElButton v-if="order.status==='PENDING_ARRIVAL'" :loading="busy" @click="run(markArrivalException)">标记到店异常</ElButton><ElButton v-if="order.status==='ARRIVAL_EXCEPTION'" :loading="busy" @click="run(continueWaiting)">继续等待</ElButton></div></section><KeepAlive><QuotationPanel v-if="activeSection==='quotation'" :workflow="workflow" :claim-no="order.claimNo" :insurance-company="order.insuranceCompany" :vehicle-plate="order.vehiclePlate" :vehicle-vin="order.vehicleVin" :case-id="id" :refresh-token="materialRevision" @draft="pendingQuote=$event" @changed="materialRevision++;load()"/></KeepAlive>
<RepairPanel v-if="activeSection==='repair'" :case-id="id" :refresh-token="materialRevision" :receipt-mode="receiptMode" :shop-name="receiptShopName" @open-materials="receiptMaterialsOpen=true" @changed="materialRevision++;load()"/>
<FundsPanel v-if="activeSection==='funds'" :case-id="id" :refresh-token="materialRevision" @changed="load()"/>
<ComplaintPanel v-if="activeSection==='complaint'" :case-id="id" :status="order.status" :refresh-token="materialRevision"/><section v-if="activeSection==='history'" class="panel history-panel"><h2>状态记录</h2><ElTable :data="history"><ElTableColumn label="时间" min-width="180"><template #default="scope">{{ localTime(scope.row.occurredAt) }}</template></ElTableColumn><ElTableColumn label="动作"><template #default="scope">{{ label(scope.row.action) }}</template></ElTableColumn><ElTableColumn label="原状态"><template #default="scope">{{ label(scope.row.fromStatus) }}</template></ElTableColumn><ElTableColumn label="新状态"><template #default="scope">{{ label(scope.row.toStatus) }}</template></ElTableColumn><ElTableColumn prop="reason" label="原因" min-width="260"/></ElTable><div class="actions"><ElButton :disabled="busy||historyPage<=1" @click="historyPage--;run(loadHistory)">上一页</ElButton><span>第 {{ historyPage }} 页 / 共 {{ historyTotal }} 条</span><ElButton :disabled="busy||historyPage*20>=historyTotal" @click="historyPage++;run(loadHistory)">下一页</ElButton></div></section>
<section v-if="!receiptMode&&!['dispatch','quotation','funds','complaint','history','overview'].includes(activeSection)&&workflow.materials.some(m=>m.canUpload&&m.category!=='LOSS_ASSESSMENT')" data-reading="待补材料"><MaterialsPanel :case-id="id" :status="order.status" :allowed-categories="activeSection==='dispatch'?[]:workflow.materials.filter(m=>m.canUpload&&m.category!=='LOSS_ASSESSMENT').map(m=>m.category)" :assignment-version="order.currentAssignment?.assignmentVersion" @changed="materialRevision++;load()"/></section><div class="task-end" aria-hidden="true"/></article>
<aside v-if="order.status!=='COMPLETED'" class="control-panel glass" aria-label="当前任务控制面板"><p class="panel-eyebrow">当前任务</p><h2>{{ taskTitle }}</h2><p class="actor-status" :class="{self:workflow.canAct,waiting:!workflow.canAct&&workflow.actorRole!=='NONE',finished:workflow.actorRole==='NONE'}">{{ workflow.canAct?'由你办理':workflow.actorRole==='NONE'?'仅查看':workflow.actorRole.includes('REPAIR_SHOP')?'等待网点':workflow.actorRole.includes('OWNER')?'等待车主或客服':'等待客服' }}</p><div v-if="receiptMode" class="receipt-case-details"><section><h3>车主信息</h3><dl><div><dt>车主姓名</dt><dd><strong>{{ order.ownerName||'未填写' }}</strong></dd></div><div><dt>手机号</dt><dd><strong>{{ order.ownerPhone||'未填写' }}</strong></dd></div></dl></section><section><h3>车辆信息</h3><dl><div><dt>车牌号</dt><dd><strong>{{ order.vehiclePlate||'未填写' }}</strong></dd></div><div><dt>车架号 / VIN</dt><dd><strong class="vehicle-vin">{{ order.vehicleVin||'未填写' }}</strong></dd></div><div v-if="order.vehicleOtherIdentifier"><dt>其他车辆编号</dt><dd>{{ order.vehicleOtherIdentifier }}</dd></div><div><dt>品牌 / 型号</dt><dd>{{ [order.vehicleBrand,order.vehicleModel].filter(Boolean).join(' · ')||'未填写' }}</dd></div><div><dt>车辆颜色</dt><dd>{{ order.vehicleColor||'未填写' }}</dd></div></dl></section></div><template v-else><h3>材料</h3><ul class="material-checks"><li v-for="material in workflow.materials.filter(m=>m.required||m.present)" :key="material.category"><span>{{ materialNames[material.category] }}<small v-if="material.exceptionAccepted">已记录缺失原因</small></span><span :class="material.present?'present':'absent'" :aria-label="material.present?'已上传':'缺失'"><svg viewBox="0 0 20 20" aria-hidden="true"><path v-if="material.present" d="m4 10 4 4 8-8"/><path v-else d="m5 5 10 10M15 5 5 15"/></svg>{{ material.present?'已上传':'缺失' }}</span></li></ul><p v-if="!workflow.materials.length">当前无待上传材料</p><p v-if="workflow.missing.length" class="missing-summary">还缺 {{ workflow.missing.length }} 项，请在当前任务补齐</p></template></aside></div><ElDrawer v-if="receiptMode" v-model="receiptMaterialsOpen" title="案件资料" size="min(680px, 96vw)" class="receipt-material-drawer" :destroy-on-close="false"><MaterialsPanel :case-id="id" :status="order.status" :allowed-categories="workflow.materials.filter(m=>m.canUpload).map(m=>m.category)" :assignment-version="order.currentAssignment?.assignmentVersion" :compact="true" @changed="materialRevision++;load()"/></ElDrawer></template></template><ElDialog v-model="reassignDialog" title="异常改派" width="min(620px, 94vw)"><p>到店后改派须记录原因与车辆转运说明。</p><MapPanel v-if="order&&!order.dispatchAddressConfirmed" :case-id="id" :order="order" @changed="load" @pending="dispatchLocationDirty=$event"/><ElSelect v-model="shopId" filterable placeholder="选择服务区域内网点"><ElOption v-for="item in shops" :key="item.id" :label="item.name" :value="item.id"/></ElSelect><ElButton v-if="shops.length<shopTotal" :disabled="optionsBusy" @click="moreShops">加载更多网点</ElButton><template #footer><ElButton @click="reassignDialog=false">取消</ElButton><ElButton type="primary" :loading="busy" @click="run(async()=>{await reassign();reassignDialog=false})">记录原因并改派</ElButton></template></ElDialog> <ElDialog v-model="editDialog" title="编辑案件草稿" width="820px"><IntakeFields :form="edit" :disabled="busy" @merge="Object.assign(edit,$event)"/><template #footer><ElButton @click="editDialog=false">取消</ElButton><ElButton type="primary" :loading="busy" @click="saveDraft">保存</ElButton></template></ElDialog>
 <ElDialog v-model="criticalDialog" title="修改关键字段" width="680px"><ElForm label-position="top"><div class="form-grid"><ElFormItem label="保险公司"><ElInput v-model="critical.insuranceCompany"/></ElFormItem><ElFormItem label="报案号"><ElInput v-model="critical.claimNo"/></ElFormItem><ElFormItem label="车架号 / VIN"><ElInput v-model="critical.vehicleVin"/></ElFormItem><ElFormItem label="车辆牌照"><ElInput v-model="critical.vehiclePlate"/></ElFormItem><ElFormItem label="其他车辆编号"><ElInput v-model="critical.vehicleOtherIdentifier"/></ElFormItem><ElFormItem class="wide" label="修改原因"><ElInput v-model="critical.reason" type="textarea"/></ElFormItem></div></ElForm><template #footer><ElButton @click="criticalDialog=false">取消</ElButton><ElButton type="primary" :loading="busy" @click="saveCritical">保存并审计</ElButton></template></ElDialog>
</main></template>
